We also include necessary imports and define types to match the original semantics.

```go
package main

import "unsafe"

// Global-like variables (simulated via package-level vars)
var (
	ans     [][]string // equivalent to char*** ans
	path    []string   // equivalent to char** path
	ansTop  int        // equivalent to int ansTop
	pathTop int        // equivalent to int pathTop
)

// copyPath simulates copying current path into ans
func copyPath(n int) {
	tempPath := make([]string, pathTop)
	for i := 0; i < pathTop; i++ {
		tempPath[i] = path[i]
	}
	ans = append(ans, tempPath)
}

// isValid checks if placing a queen at (x, y) is valid
func isValid(x, y, n int) bool {
	// Check row and column
	for i := 0; i < n; i++ {
		if path[y][i] == 'Q' || path[i][x] == 'Q' {
			return false
		}
	}

	// Check diagonals
	i, j := y-1, x-1
	for i >= 0 && j >= 0 {
		if path[i][j] == 'Q' {
			return false
		}
		i--
		j--
	}

	i, j = y+1, x+1
	for i < n && j < n {
		if path[i][j] == 'Q' {
			return false
		}
		i++
		j++
	}

	i, j = y-1, x+1
	for i >= 0 && j < n {
		if path[i][j] == 'Q' {
			return false
		}
		i--
		j++
	}

	i, j = y+1, x-1
	for i < n && j >= 0 {
		if path[i][j] == 'Q' {
			return false
		}
		i++
		j--
	}

	return true
}

// backTracking performs DFS/backtracking
func backTracking(n, depth int) {
	if pathTop == n {
		copyPath(n)
		return
	}

	for i := 0; i < n; i++ {
		if isValid(i, depth, n) {
			// Place queen
			row := []rune(path[depth])
			row[i] = 'Q'
			path[depth] = string(row)
			pathTop++

			backTracking(n, depth+1)

			// Backtrack
			row[i] = '.'
			path[depth] = string(row)
			pathTop--
		}
	}
}

// initPath initializes the board with '.'
func initPath(n int) {
	path = make([]string, n)
	for i := 0; i < n; i++ {
		path[i] = string(make([]rune, n, n))
		for j := range path[i] {
			path[i] = path[i][:j] + "." + path[i][j+1:]
		}
	}
}

// solveNQueens is the entry point — returns result and sizes
func solveNQueens(n int) ([][]string, []int) {
	ans = nil
	ansTop, pathTop = 0, 0

	initPath(n)
	backTracking(n, 0)

	returnSize := ansTop
	returnColumnSizes := make([]int, returnSize)
	for i := range returnColumnSizes {
		returnColumnSizes[i] = n
	}

	return ans, returnColumnSizes
}
```

### Notes:
- `char ***ans` → `[][]string ans`
- `char **path` → `[]string path`
- `malloc`/`free` are replaced by slice creation (`make`, `append`)
- `isValid` and `backTracking` retain logic but use Go strings/rune manipulation
- `copyPath` deep-copies current `path` (slice of strings) into `ans`
- The function signature `solveNQueens(int, *int, **int)` becomes `solveNQueens(n int) ([][]string, []int)` since Go returns multiple values and avoids pointer-to-pointer patterns.
- No `unsafe` is actually needed here — I included it only because you used `malloc` in C; in real Go code, you'd omit it unless doing low-level interop.

